#Requires -Version 5.1
# HS Tech - Central de Diagnostico e Orcamento
$ErrorActionPreference='SilentlyContinue'
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
[Windows.Forms.Application]::EnableVisualStyles()
$script:data=[ordered]@{}
function Log($s){$log.AppendText(('[{0}] {1}{2}' -f (Get-Date -Format HH:mm:ss),$s,[Environment]::NewLine))}
function Scan {
 $d=[ordered]@{};Log 'Coletando dados do PC...'
 try{$cs=Get-CimInstance Win32_ComputerSystem;$cpu=Get-CimInstance Win32_Processor|Select-Object -First 1;$os=Get-CimInstance Win32_OperatingSystem
 $d['Computador']=$cs.Name;$d['Modelo']="$($cs.Manufacturer) $($cs.Model)";$d['CPU']=$cpu.Name;$d['RAM total GB']=[math]::Round($cs.TotalPhysicalMemory/1GB,2);$d['RAM em uso %']=[math]::Round(100*($os.TotalVisibleMemorySize-$os.FreePhysicalMemory)/$os.TotalVisibleMemorySize,1);$d['Windows']="$($os.Caption) $($os.Version) build $($os.BuildNumber)";$d['Ultima inicializacao']=$os.LastBootUpTime}catch{Log 'Falha ao ler parte dos dados basicos.'}
 try{$d['GPU']=(Get-CimInstance Win32_VideoController|ForEach-Object{"$($_.Name), driver $($_.DriverVersion)"}) -join '; '}catch{$d['GPU']='Nao disponivel'}
 try{$d['Unidades']=(Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=3'|ForEach-Object{"$($_.DeviceID): livre $([math]::Round($_.FreeSpace/1GB,1))/$([math]::Round($_.Size/1GB,1)) GB"}) -join '; '}catch{$d['Unidades']='Nao disponivel'}
 try{$p=@(Get-PhysicalDisk|ForEach-Object{"$($_.FriendlyName): $($_.MediaType), estado $($_.HealthStatus), $([math]::Round($_.Size/1GB,1)) GB"});if($p.Count){$d['Estado informado dos discos']=$p -join '; '}else{$d['SMART/saude']='API nao retornou dados; nao confirma defeito.'}}catch{$d['SMART/saude']='Nao disponivel'}
 try{$t=@(Get-CimInstance -Namespace root/wmi -ClassName MSAcpi_ThermalZoneTemperature|ForEach-Object{[math]::Round($_.CurrentTemperature/10-273.15,1)}|Where-Object{$_ -gt 0 -and $_ -lt 130});if($t.Count){$d['Temperatura ACPI (nao necessariamente CPU)']=$t -join ', '}else{$d['Temperatura']='Sensor nao exposto pelo sistema'}}catch{$d['Temperatura']='Sensor nao disponivel'}
 try{$m=Get-MpComputerStatus;$d['Defender ativo']=$m.AntivirusEnabled;$d['Protecao em tempo real']=$m.RealTimeProtectionEnabled}catch{$d['Defender']='Estado indisponivel ou outro antivirus instalado'}
 try{$d['Itens de inicializacao']=@(Get-CimInstance Win32_StartupCommand).Count}catch{$d['Itens de inicializacao']='Nao disponivel'}
 $script:data=$d;foreach($k in $d.Keys){Log "$k : $($d[$k])"};Log 'Coleta concluida. Leituras de sensores/SMART dependem do hardware.'
}
function E($s){[Net.WebUtility]::HtmlEncode([string]$s)}
function Report {
 if(!$script:data.Count){[Windows.Forms.MessageBox]::Show('Execute o diagnostico primeiro.');return}
 $folder=Join-Path ([Environment]::GetFolderPath('MyDocuments')) 'HS-Tech-Relatorios';if(!(Test-Path $folder)){New-Item -ItemType Directory -Path $folder -Force|Out-Null}
 $rows='';foreach($k in $script:data.Keys){$rows+="<tr><th>$(E $k)</th><td>$(E $script:data[$k])</td></tr>"}
 $a=0.0;$b=0.0;[void][double]::TryParse($pecas.Text.Replace(',','.'),[Globalization.NumberStyles]::Any,[Globalization.CultureInfo]::InvariantCulture,[ref]$a);[void][double]::TryParse($mao.Text.Replace(',','.'),[Globalization.NumberStyles]::Any,[Globalization.CultureInfo]::InvariantCulture,[ref]$b);$total=($a+$b).ToString('N2',[Globalization.CultureInfo]::GetCultureInfo('pt-BR'))
 $path=Join-Path $folder ('Laudo-HSTech-{0}.html' -f (Get-Date -Format yyyyMMdd-HHmmss))
 $html=@"
<!doctype html><html lang="pt-br"><meta charset="utf-8"><title>Laudo HS Tech</title><style>body{font:15px Arial;margin:30px;color:#222}header{background:#111;color:white;padding:22px;border-left:8px solid #d2232b}h1{color:#f33}h2{border-bottom:2px solid #ddd}table{width:100%;border-collapse:collapse}td,th{border:1px solid #ddd;padding:8px;text-align:left;vertical-align:top}th{background:#eee;width:30%}.total{font-size:22px;color:#b21d26;font-weight:bold}.small{font-size:12px;color:#555}</style><body><header><h1>HS ASSISTENCIA TECNICA</h1><p>HS Tech | Laudo de diagnostico e orcamento</p></header>
<h2>Atendimento</h2><p>Data: $(Get-Date -Format 'dd/MM/yyyy HH:mm')</p><p>Cliente: $(E $cliente.Text)</p><p>Contato: $(E $contato.Text)</p><p>Sintoma relatado: $(E $sintoma.Text)</p><h2>Dados coletados</h2><table>$rows</table><h2>Orcamento</h2><p>Servico: $(E $servico.Text)</p><p>Pecas R$: $(E $pecas.Text) | Mao de obra R$: $(E $mao.Text)</p><p class="total">Total estimado R$ $total</p><p>Observacoes: $(E $obs.Text)</p><p class="small">Dados de software sao indicativos. Dados indisponiveis nao comprovam defeito nem funcionamento correto. Defeitos fisicos exigem testes apropriados. Orcamento sujeito a confirmacao e autorizacao do cliente.</p></body></html>
"@
 [IO.File]::WriteAllText($path,$html,[Text.UTF8Encoding]::new($true));Log "Laudo salvo: $path";[Windows.Forms.MessageBox]::Show("Laudo salvo em $path. Abra no navegador e use Imprimir para salvar como PDF.",'HS Tech')|Out-Null
}
$f=New-Object Windows.Forms.Form;$f.Text='HS Tech | Diagnostico e Orcamento';$f.Size=New-Object Drawing.Size(980,700);$f.StartPosition='CenterScreen';$f.BackColor=[Drawing.Color]::FromArgb(12,12,16)
$h=New-Object Windows.Forms.Label;$h.Text='HS TECH | CENTRAL DE DIAGNOSTICO';$h.Location=New-Object Drawing.Point(20,15);$h.Size=New-Object Drawing.Size(850,42);$h.Font=New-Object Drawing.Font('Segoe UI',20,[Drawing.FontStyle]::Bold);$h.ForeColor=[Drawing.Color]::FromArgb(235,45,52);$f.Controls.Add($h)
$tabs=New-Object Windows.Forms.TabControl;$tabs.Location=New-Object Drawing.Point(15,65);$tabs.Size=New-Object Drawing.Size(930,570)
foreach($n in @('Diagnostico','Orcamento e laudo','Cuidados')){$p=New-Object Windows.Forms.TabPage;$p.Text=$n;$p.BackColor=[Drawing.Color]::FromArgb(18,18,23);[void]$tabs.TabPages.Add($p)};$f.Controls.Add($tabs)
$p=$tabs.TabPages[0];$b=New-Object Windows.Forms.Button;$b.Text='Executar diagnostico';$b.Location=New-Object Drawing.Point(18,15);$b.Size=New-Object Drawing.Size(190,38);$b.BackColor=[Drawing.Color]::FromArgb(210,35,43);$b.ForeColor='White';$b.Add_Click({Scan});$p.Controls.Add($b)
$b2=New-Object Windows.Forms.Button;$b2.Text='Teste de memoria RAM';$b2.Location=New-Object Drawing.Point(220,15);$b2.Size=New-Object Drawing.Size(190,38);$b2.BackColor=[Drawing.Color]::FromArgb(210,35,43);$b2.ForeColor='White';$b2.Add_Click({if([Windows.Forms.MessageBox]::Show('Pode exigir reinicializacao. Salve o trabalho. Abrir ferramenta?','Aviso','YesNo','Warning') -eq 'Yes'){Start-Process "$env:SystemRoot\System32\MdSched.exe";Log 'Diagnostico de memoria aberto; teste ainda precisa ser agendado.'}});$p.Controls.Add($b2)
$script:log=New-Object Windows.Forms.TextBox;$log.Location=New-Object Drawing.Point(18,65);$log.Size=New-Object Drawing.Size(875,450);$log.Multiline=$true;$log.ScrollBars='Vertical';$log.ReadOnly=$true;$log.Anchor='Top,Bottom,Left,Right';$log.BackColor=[Drawing.Color]::FromArgb(8,8,12);$log.ForeColor='White';$log.Font=New-Object Drawing.Font('Consolas',9);$p.Controls.Add($log)
$p=$tabs.TabPages[1];foreach($z in @(@('Cliente',18,15),@('Contato',480,15),@('Sintoma',18,78),@('Servico recomendado',18,145),@('Pecas (R$)',18,220),@('Mao de obra (R$)',250,220),@('Observacoes',18,285))){$l=New-Object Windows.Forms.Label;$l.Text=$z[0];$l.Location=New-Object Drawing.Point($z[1],$z[2]);$l.Size=New-Object Drawing.Size(220,24);$l.ForeColor='White';$p.Controls.Add($l)}
$script:cliente=Box 18 40 420;$script:contato=Box 480 40 410;$script:sintoma=Box 18 103 870 30;$script:servico=Box 18 170 870 30;$script:pecas=Box 18 245 200 28 '0,00';$script:mao=Box 250 245 200 28 '0,00';$script:obs=Box 18 310 870 100;$obs.Multiline=$true;$obs.ScrollBars='Vertical';$p.Controls.AddRange(@($cliente,$contato,$sintoma,$servico,$pecas,$mao,$obs))
$b3=New-Object Windows.Forms.Button;$b3.Text='Gerar laudo tecnico';$b3.Location=New-Object Drawing.Point(18,430);$b3.Size=New-Object Drawing.Size(220,40);$b3.BackColor=[Drawing.Color]::FromArgb(210,35,43);$b3.ForeColor='White';$b3.Add_Click({Report});$p.Controls.Add($b3)
$p=$tabs.TabPages[2];$guide=New-Object Windows.Forms.TextBox;$guide.Location=New-Object Drawing.Point(18,18);$guide.Size=New-Object Drawing.Size(870,420);$guide.Multiline=$true;$guide.ReadOnly=$true;$guide.Text="Faca backup antes de reparos ou testes prolongados."+[Environment]::NewLine+"Sensores e SMART podem nao ser expostos por todos os drivers."+[Environment]::NewLine+"Nunca abra fontes de alimentacao: risco de choque mesmo desligadas."+[Environment]::NewLine+"Evite limpeza agressiva de registro e desativacao de servicos essenciais."+[Environment]::NewLine+"Testes de estabilidade geram calor; monitore temperaturas."+[Environment]::NewLine+"Software nao confirma todos os defeitos fisicos; faca inspecao e medicao."+[Environment]::NewLine+"Explique o orcamento e obtenha autorizacao antes do servico.";$p.Controls.Add($guide)
$f.Add_Shown({Log 'Pronto. Execute o diagnostico para comecar.'});[void]$f.ShowDialog()
